CREATE OR REPLACE FUNCTION public.sunland_account_delete_begin(p_user_id text, p_deletion_job_id uuid, p_attempt_id text, p_fencing_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_status text;
  v_job uuid;
  v_attempt text;
  v_version bigint;
begin
  if p_user_id is null
    or p_user_id !~ '^[A-Za-z0-9][A-Za-z0-9@._+-]{0,127}$'
    or p_deletion_job_id is null
    or p_attempt_id is null
    or p_attempt_id !~ '^[A-Za-z0-9_-]{16,128}$'
    or p_fencing_version is null
    or p_fencing_version < 1 then
    return jsonb_build_object('code', 'invalid_request');
  end if;

  select identity_status, deletion_job_id, deletion_attempt_id, deletion_fencing_version
    into v_status, v_job, v_attempt, v_version
  from public.user_profiles
  where user_id = p_user_id
  for update;

  if not found then
    return jsonb_build_object(
      'code', 'user_not_found',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id
    );
  end if;

  if v_status = 'retired' then
    return jsonb_build_object(
      'code', 'retired',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', v_attempt,
      'fencing_version', v_version
    );
  end if;

  if v_status = 'deleting' then
    if v_job is distinct from p_deletion_job_id then
      return jsonb_build_object(
        'code', 'deletion_conflict',
        'deletion_job_id', p_deletion_job_id::text,
        'user_id', p_user_id,
        'attempt_id', v_attempt,
        'fencing_version', v_version
      );
    end if;

    if p_fencing_version < v_version then
      return jsonb_build_object(
        'code', 'stale_attempt',
        'deletion_job_id', p_deletion_job_id::text,
        'user_id', p_user_id,
        'attempt_id', v_attempt,
        'fencing_version', v_version
      );
    end if;

    if p_fencing_version = v_version then
      if p_attempt_id is distinct from v_attempt then
        return jsonb_build_object(
          'code', 'fencing_conflict',
          'deletion_job_id', p_deletion_job_id::text,
          'user_id', p_user_id,
          'attempt_id', v_attempt,
          'fencing_version', v_version
        );
      end if;

      return jsonb_build_object(
        'code', 'already_revoked',
        'deletion_job_id', p_deletion_job_id::text,
        'user_id', p_user_id,
        'attempt_id', v_attempt,
        'fencing_version', v_version
      );
    end if;

    update public.user_profiles
       set deletion_attempt_id = p_attempt_id,
           deletion_fencing_version = p_fencing_version,
           deletion_started_at = now()
     where user_id = p_user_id;

    return jsonb_build_object(
      'code', 'ownership_transferred',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', p_attempt_id,
      'fencing_version', p_fencing_version
    );
  end if;

  if v_status = 'active' then
    update public.user_profiles
       set identity_status = 'deleting',
           deletion_job_id = p_deletion_job_id,
           deletion_attempt_id = p_attempt_id,
           deletion_fencing_version = p_fencing_version,
           deletion_started_at = now()
     where user_id = p_user_id;

    return jsonb_build_object(
      'code', 'revoked',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', p_attempt_id,
      'fencing_version', p_fencing_version
    );
  end if;

  return jsonb_build_object(
    'code', 'invalid_state',
    'deletion_job_id', p_deletion_job_id::text,
    'user_id', p_user_id,
    'attempt_id', v_attempt,
    'fencing_version', v_version
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sunland_account_delete_finalize(p_user_id text, p_deletion_job_id uuid, p_attempt_id text, p_fencing_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_status text;
  v_job uuid;
  v_attempt text;
  v_version bigint;
begin
  if p_user_id is null
    or p_user_id !~ '^[A-Za-z0-9][A-Za-z0-9@._+-]{0,127}$'
    or p_deletion_job_id is null
    or p_attempt_id is null
    or p_attempt_id !~ '^[A-Za-z0-9_-]{16,128}$'
    or p_fencing_version is null
    or p_fencing_version < 1 then
    return jsonb_build_object('code', 'invalid_request');
  end if;

  select identity_status, deletion_job_id, deletion_attempt_id, deletion_fencing_version
    into v_status, v_job, v_attempt, v_version
  from public.user_profiles
  where user_id = p_user_id
  for update;

  if not found then
    return jsonb_build_object(
      'code', 'user_not_found',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', v_attempt,
      'fencing_version', v_version
    );
  end if;

  if v_status = 'retired' then
    if v_job = p_deletion_job_id
      and v_attempt = p_attempt_id
      and v_version = p_fencing_version then
      return jsonb_build_object(
        'code', 'already_retired',
        'deletion_job_id', p_deletion_job_id::text,
        'user_id', p_user_id,
        'attempt_id', v_attempt,
        'fencing_version', v_version
      );
    end if;

    return jsonb_build_object(
      'code', 'stale_attempt',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', v_attempt,
      'fencing_version', v_version
    );
  end if;

  if v_status = 'active' then
    return jsonb_build_object(
      'code', 'not_deleting',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', v_attempt,
      'fencing_version', v_version
    );
  end if;

  if v_status = 'deleting' then
    if v_job is distinct from p_deletion_job_id then
      return jsonb_build_object(
        'code', 'deletion_conflict',
        'deletion_job_id', p_deletion_job_id::text,
        'user_id', p_user_id,
        'attempt_id', v_attempt,
        'fencing_version', v_version
      );
    end if;

    if p_fencing_version is distinct from v_version then
      return jsonb_build_object(
        'code', 'stale_attempt',
        'deletion_job_id', p_deletion_job_id::text,
        'user_id', p_user_id,
        'attempt_id', v_attempt,
        'fencing_version', v_version
      );
    end if;

    if p_attempt_id is distinct from v_attempt then
      return jsonb_build_object(
        'code', 'fencing_conflict',
        'deletion_job_id', p_deletion_job_id::text,
        'user_id', p_user_id,
        'attempt_id', v_attempt,
        'fencing_version', v_version
      );
    end if;

    update public.user_profiles
       set identity_status = 'retired',
           retired_at = now()
     where user_id = p_user_id;

    return jsonb_build_object(
      'code', 'retired',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', v_attempt,
      'fencing_version', v_version
    );
  end if;

  return jsonb_build_object(
    'code', 'invalid_state',
    'deletion_job_id', p_deletion_job_id::text,
    'user_id', p_user_id,
    'attempt_id', v_attempt,
    'fencing_version', v_version
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sunland_account_delete_sanitize_profile(p_user_id text, p_deletion_job_id uuid, p_attempt_id text, p_fencing_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_status text;
  v_job uuid;
  v_attempt text;
  v_version bigint;
  v_sanitized_at timestamptz;
begin
  if p_user_id is null
    or p_user_id !~ '^[A-Za-z0-9][A-Za-z0-9@._+-]{0,127}$'
    or p_deletion_job_id is null
    or p_attempt_id is null
    or p_attempt_id !~ '^[A-Za-z0-9_-]{16,128}$'
    or p_fencing_version is null
    or p_fencing_version < 1 then
    return jsonb_build_object('code', 'invalid_request');
  end if;

  select identity_status, deletion_job_id, deletion_attempt_id, deletion_fencing_version, profile_sanitized_at
    into v_status, v_job, v_attempt, v_version, v_sanitized_at
  from public.user_profiles
  where user_id = p_user_id
  for update;

  if not found then
    return jsonb_build_object(
      'code', 'user_not_found',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', p_attempt_id,
      'fencing_version', p_fencing_version
    );
  end if;

  if v_status is distinct from 'retired' then
    return jsonb_build_object(
      'code', 'not_retired',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', v_attempt,
      'fencing_version', v_version
    );
  end if;

  if v_job is distinct from p_deletion_job_id
    or v_version is distinct from p_fencing_version then
    return jsonb_build_object(
      'code', 'stale_attempt',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', v_attempt,
      'fencing_version', v_version
    );
  end if;

  if v_attempt is distinct from p_attempt_id then
    return jsonb_build_object(
      'code', 'fencing_conflict',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', v_attempt,
      'fencing_version', v_version
    );
  end if;

  if v_sanitized_at is not null then
    return jsonb_build_object(
      'code', 'already_sanitized',
      'deletion_job_id', p_deletion_job_id::text,
      'user_id', p_user_id,
      'attempt_id', v_attempt,
      'fencing_version', v_version
    );
  end if;

  update public.user_profiles
     set email = null,
         avatar_url = null,
         avatar_path = null,
         name = null,
         pro = false,
         is_banned = false,
         ban_reason = null,
         updated_at = now(),
         profile_sanitized_at = now()
   where user_id = p_user_id;

  return jsonb_build_object(
    'code', 'sanitized',
    'deletion_job_id', p_deletion_job_id::text,
    'user_id', p_user_id,
    'attempt_id', p_attempt_id,
    'fencing_version', p_fencing_version
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.sunland_authenticated_identity_is_active(p_user_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_claimed_user_id text;
  v_identity_status text;
begin
  if coalesce((select auth.jwt() ->> 'role'), '') <> 'authenticated' then
    return false;
  end if;
  v_claimed_user_id := nullif((select auth.jwt() ->> 'id'), '');
  if v_claimed_user_id is distinct from p_user_id then
    return false;
  end if;

  select identity_status into v_identity_status
    from public.user_profiles
   where user_id = p_user_id
   for no key update;
  return found and v_identity_status = 'active';
end;
$function$

CREATE OR REPLACE FUNCTION public.sunland_claim_account_deletion_job(p_job_id uuid, p_token_hash text, p_attempt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'extensions'
AS $function$
declare
  v_user_id text;
  v_attempt_id text;
  v_fencing_version bigint;
  v_now timestamptz := now();
begin
  if p_job_id is null or p_token_hash is null or p_attempt_id is null then
    return null;
  end if;

  if p_attempt_id !~ '^[A-Za-z0-9_-]{16,128}$' then
    return null;
  end if;

  update public.account_deletion_jobs
     set status = 'in_progress',
         claimed_at = v_now,
         lease_expires_at = v_now + interval '90 seconds',
         attempt_id = p_attempt_id,
         fencing_version = fencing_version +
           case
             when status = 'pending' or attempt_id is distinct from p_attempt_id then 1
             else 0
           end,
         recovery_expires_at = v_now + interval '7 days'
   where id = p_job_id
     and token_hash = p_token_hash
     and (
       (
         status = 'pending'
         and expires_at > v_now
       )
       or (
         status = 'in_progress'
         and (
           attempt_id = p_attempt_id
           or lease_expires_at is null
           or lease_expires_at < v_now
         )
         and recovery_expires_at > v_now
       )
     )
  returning user_id, attempt_id, fencing_version
    into v_user_id, v_attempt_id, v_fencing_version;

  if v_user_id is null then
    return null;
  end if;

  return jsonb_build_object(
    'user_id', v_user_id,
    'attempt_id', v_attempt_id,
    'fencing_version', v_fencing_version
  );
end;
$function$
